{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C05","C19","C23","C52","C53","C54","C55","C57"],
  "contradictory_card_ids": ["C04","C07","C10","C11","C13","C48"],
  "prediction_basis_card_ids": ["C05","C19","C23","C52","C53","C54","C55","C57"],
  "claims": [
    {
      "claim": "L5 shows that the close morphinan analog morphine undergoes intestinal P-gp efflux (C52, C54, C55) and extensive small-intestinal UGT glucuronidation (C53, C57), providing mechanistic evidence for presystemic loss that supports F<20% for the similarly phenolic morphinan nalbuphine, though these are not direct F measurements.",
      "card_ids": ["C52","C53","C54","C55","C57"]
    },
    {
      "claim": "Samidorphan, a structurally related morphinan, has high Caco-2 A-B Papp (18.77 x 10^-6 cm/s, C48), suggesting permeability is not the limiting step, but this does not address first-pass metabolism and does not provide an oral F estimate.",
      "card_ids": ["C48"]
    },
    {
      "claim": "The meptazinol cirrhotic F of 27.9±5.3% with a four-fold increase over controls implies a non-cirrhotic control F near 7% (C05, C19, C23); L5 gut-wall efflux/metabolism evidence strengthens the analogy that phenolic morphinans undergo substantial presystemic loss.",
      "card_ids": ["C05","C19","C23","C52","C53","C54","C55","C57"]
    },
    {
      "claim": "High-F contexts remain cirrhosis-dependent (pentazocine C04/C11, meperidine C07/C13, ciramadol C10) or structurally unrelated (paliperidone C01/C15, haloperidol C08/C14, BI 425809 C09, ACT-1004-1239 C03/C06, UDCA C12); none provides affirmative evidence for F>=20% in the non-cirrhotic query.",
      "card_ids": ["C01","C03","C04","C06","C07","C08","C09","C10","C11","C12","C13","C14","C15"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C52","C53","C54","C55","C57"]
    }
  ],
  "evidence_gaps": [
    "No direct nalbuphine-specific absolute oral bioavailability measurement is present in the supplied records.",
    "No nalbuphine-specific gut-wall efflux or intestinal metabolism experiment is provided; L5 records are for morphine, samidorphan, ethinyl estradiol, topotecan/irinotecan, and RRCK compounds.",
    "The meptazinol control F (~7%) is inferred from the stated four-fold increase over controls rather than reported as a direct numeric control value.",
    "Samidorphan Caco-2 A-B Papp is high, but no F or efflux ratio is available for nalbuphine.",
    "Normal-condition F values for pentazocine, meperidine, and ciramadol are not directly provided; their high-F contexts are cirrhosis-dependent.",
    "The extent of nalbuphine first-pass glucuronidation is not quantified in the supplied evidence."
  ],
  "decision_summary": "L5 gut-wall efflux/intestinal metabolism records show that the close analog morphine undergoes intestinal P-gp efflux and UGT glucuronidation, providing mechanistic support for presystemic loss; combined with the meptazinol control-F inference (~7%), the evidence supports F<20%. No direct nalbuphine F is available, and high-F contexts are cirrhosis-dependent or unrelated, so prediction remains low with moderate confidence."
}

